create or replace function private.owner_upsert_supplier(
  p_business_id uuid,p_supplier_id uuid,p_display_name text,p_contact_name text,
  p_phone text,p_email text,p_notes text,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_actor uuid; v_cached jsonb; v_payload jsonb; v_id uuid; v_created boolean; v_result jsonb;
begin
  v_actor:=private.assert_active_owner(p_business_id);
  if length(btrim(coalesce(p_display_name,''))) not between 1 and 180
    or length(coalesce(p_contact_name,''))>120 or length(coalesce(p_phone,''))>40
    or length(coalesce(p_email,''))>254 or length(coalesce(p_notes,''))>4000 then
    raise exception using errcode='22023',message='Supplier fields exceed allowed limits';
  end if;
  if p_email is not null and p_email !~* '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' then
    raise exception using errcode='22023',message='Invalid supplier email';
  end if;
  v_payload:=jsonb_build_object('supplier_id',p_supplier_id,'display_name',p_display_name,'contact_name',p_contact_name,
    'phone',p_phone,'email',p_email,'notes',p_notes);
  v_cached:=private.begin_idempotent_request(p_business_id,'upsert_supplier',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  if p_supplier_id is null then
    insert into public.suppliers(business_id,display_name,contact_name,phone,email,notes)
    values(p_business_id,btrim(p_display_name),nullif(btrim(p_contact_name),''),nullif(btrim(p_phone),''),
      nullif(lower(btrim(p_email)),''),p_notes)
    returning id into v_id;
    v_created:=true;
  else
    update public.suppliers set display_name=btrim(p_display_name),contact_name=nullif(btrim(p_contact_name),''),
      phone=nullif(btrim(p_phone),''),email=nullif(lower(btrim(p_email)),''),notes=p_notes,updated_at=now()
    where business_id=p_business_id and id=p_supplier_id and archived_at is null returning id into v_id;
    if v_id is null then raise exception using errcode='P0002',message='Supplier not found or archived'; end if;
    v_created:=false;
  end if;
  v_result:=jsonb_build_object('supplier_id',v_id,'created',v_created);
  perform private.finish_idempotent_request(p_business_id,'upsert_supplier',p_request_id,v_result);
  perform private.write_audit(p_business_id,v_actor,case when v_created then 'supplier.created' else 'supplier.updated' end,
    'supplier',v_id,p_request_id,'{}'::jsonb);
  return v_result;
end;
$$;

create or replace function private.owner_upsert_stock_item(
  p_business_id uuid,p_stock_item_id uuid,p_parent_stock_item_id uuid,p_sku text,p_name text,
  p_stock_kind text,p_base_unit text,p_purchase_unit text,p_purchase_to_base_factor numeric,
  p_roll_width_mm numeric,p_usable_width_mm numeric,p_variant_attributes jsonb,
  p_reorder_level numeric,p_default_supplier_id uuid,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_actor uuid; v_cached jsonb; v_payload jsonb; v_id uuid; v_created boolean; v_result jsonb;
  v_existing public.stock_items%rowtype;
begin
  v_actor:=private.assert_active_owner(p_business_id);
  if length(btrim(coalesce(p_sku,''))) not between 1 and 80 or length(btrim(coalesce(p_name,''))) not between 1 and 180
    or p_stock_kind is null or p_stock_kind not in ('blank_product','material','consumable','packaging')
    or length(btrim(coalesce(p_base_unit,''))) not between 1 and 24
    or length(btrim(coalesce(p_purchase_unit,''))) not between 1 and 24
    or p_purchase_to_base_factor is null or p_purchase_to_base_factor<=0
    or (p_roll_width_mm is null)<>(p_usable_width_mm is null)
    or (p_roll_width_mm is not null and (p_roll_width_mm<=0 or p_usable_width_mm<=0 or p_usable_width_mm>p_roll_width_mm))
    or coalesce(p_reorder_level,0)<0
    or jsonb_typeof(coalesce(p_variant_attributes,'{}'::jsonb))<>'object' then
    raise exception using errcode='22023',message='Invalid stock item details';
  end if;
  if p_parent_stock_item_id is not null and not exists(select 1 from public.stock_items where business_id=p_business_id and id=p_parent_stock_item_id) then
    raise exception using errcode='22023',message='Parent stock item belongs to another business or does not exist';
  end if;
  if p_default_supplier_id is not null and not exists(select 1 from public.suppliers where business_id=p_business_id and id=p_default_supplier_id and archived_at is null) then
    raise exception using errcode='22023',message='Default supplier belongs to another business or is archived';
  end if;
  v_payload:=jsonb_build_object('stock_item_id',p_stock_item_id,'parent_stock_item_id',p_parent_stock_item_id,'sku',p_sku,
    'name',p_name,'stock_kind',p_stock_kind,'base_unit',p_base_unit,'purchase_unit',p_purchase_unit,
    'factor',p_purchase_to_base_factor,'roll_width_mm',p_roll_width_mm,'usable_width_mm',p_usable_width_mm,
    'variant_attributes',coalesce(p_variant_attributes,'{}'::jsonb),'reorder_level',p_reorder_level,'supplier_id',p_default_supplier_id);
  v_cached:=private.begin_idempotent_request(p_business_id,'upsert_stock_item',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  if p_stock_item_id is null then
    insert into public.stock_items(business_id,parent_stock_item_id,sku,name,stock_kind,base_unit,purchase_unit,
      purchase_to_base_factor,roll_width_mm,usable_width_mm,variant_attributes,reorder_level,default_supplier_id)
    values(p_business_id,p_parent_stock_item_id,upper(btrim(p_sku)),btrim(p_name),p_stock_kind,btrim(p_base_unit),
      btrim(p_purchase_unit),p_purchase_to_base_factor,p_roll_width_mm,p_usable_width_mm,
      coalesce(p_variant_attributes,'{}'::jsonb),coalesce(p_reorder_level,0),p_default_supplier_id)
    returning id into v_id;
    v_created:=true;
  else
    select * into v_existing from public.stock_items where business_id=p_business_id and id=p_stock_item_id for update;
    if not found then raise exception using errcode='P0002',message='Stock item not found'; end if;
    if exists(select 1 from public.stock_movements where business_id=p_business_id and stock_item_id=p_stock_item_id)
       and (v_existing.base_unit<>p_base_unit or v_existing.purchase_unit<>p_purchase_unit
         or v_existing.purchase_to_base_factor<>p_purchase_to_base_factor) then
      raise exception using errcode='22023',message='Units and conversion factor cannot change after stock movements exist';
    end if;
    update public.stock_items set parent_stock_item_id=p_parent_stock_item_id,sku=upper(btrim(p_sku)),name=btrim(p_name),
      stock_kind=p_stock_kind,base_unit=btrim(p_base_unit),purchase_unit=btrim(p_purchase_unit),
      purchase_to_base_factor=p_purchase_to_base_factor,roll_width_mm=p_roll_width_mm,usable_width_mm=p_usable_width_mm,
      variant_attributes=coalesce(p_variant_attributes,'{}'::jsonb),reorder_level=coalesce(p_reorder_level,0),
      default_supplier_id=p_default_supplier_id,updated_at=now()
    where business_id=p_business_id and id=p_stock_item_id returning id into v_id;
    v_created:=false;
  end if;
  v_result:=jsonb_build_object('stock_item_id',v_id,'created',v_created);
  perform private.finish_idempotent_request(p_business_id,'upsert_stock_item',p_request_id,v_result);
  perform private.write_audit(p_business_id,v_actor,case when v_created then 'stock_item.created' else 'stock_item.updated' end,
    'stock_item',v_id,p_request_id,'{}'::jsonb);
  return v_result;
end;
$$;

create or replace function private.owner_reserve_order_stock(p_order_id uuid,p_request_id uuid)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_order public.orders%rowtype; v_actor uuid; v_cached jsonb; v_payload jsonb;
  v_line record; v_location record; v_on_hand numeric; v_reserved numeric; v_available numeric;
  v_needed numeric; v_take numeric; v_total numeric:=0; v_count integer:=0; v_result jsonb;
begin
  select * into v_order from public.orders where id=p_order_id;
  if not found then raise exception using errcode='P0002',message='Order not found'; end if;
  v_actor:=private.assert_active_owner(v_order.business_id);
  v_payload:=jsonb_build_object('order_id',p_order_id);
  v_cached:=private.begin_idempotent_request(v_order.business_id,'reserve_order_stock',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  select * into v_order from public.orders where business_id=v_order.business_id and id=p_order_id for update;
  if v_order.status not in ('confirmed','in_production') then raise exception using errcode='22023',message='Only confirmed orders can reserve stock'; end if;

  for v_line in
    select oi.* from public.order_items oi
    where oi.business_id=v_order.business_id and oi.order_id=p_order_id
      and oi.stock_item_id is not null and oi.customer_supplies_item=false
    order by oi.id
    for update
  loop
    if v_line.sale_mode not in ('blank','value_added') then continue; end if;
    perform 1 from public.stock_items where business_id=v_order.business_id and id=v_line.stock_item_id and is_active for update;
    if not found then raise exception using errcode='22023',message='Order line references an inactive stock SKU'; end if;
    if (select base_unit from public.stock_items where business_id=v_order.business_id and id=v_line.stock_item_id)<>v_line.unit then
      raise exception using errcode='22023',message='Order line unit does not match stock SKU base unit';
    end if;
    select greatest(v_line.quantity-coalesce(sum(r.reserved_quantity-r.released_quantity),0),0)
    into v_needed from public.stock_reservations r
    where r.business_id=v_order.business_id and r.order_item_id=v_line.id and r.status='active';
    if v_needed<=0 then continue; end if;
    for v_location in
      select l.id from public.inventory_locations l where l.business_id=v_order.business_id and l.is_active order by l.code,l.id
    loop
      perform pg_advisory_xact_lock(hashtextextended(v_order.business_id::text||v_line.stock_item_id::text||v_location.id::text,0));
      select coalesce(sum(m.quantity),0) into v_on_hand from public.stock_movements m
        where m.business_id=v_order.business_id and m.stock_item_id=v_line.stock_item_id and m.location_id=v_location.id;
      select coalesce(sum(r.reserved_quantity-r.released_quantity),0) into v_reserved from public.stock_reservations r
        where r.business_id=v_order.business_id and r.stock_item_id=v_line.stock_item_id
          and r.location_id=v_location.id and r.status='active';
      v_available:=greatest(v_on_hand-v_reserved,0);
      if v_available>0 then
        v_take:=least(v_needed,v_available);
        insert into public.stock_reservations(business_id,order_item_id,stock_item_id,location_id,reserved_quantity)
        values(v_order.business_id,v_line.id,v_line.stock_item_id,v_location.id,v_take);
        v_needed:=v_needed-v_take;
        v_total:=v_total+v_take;
        v_count:=v_count+1;
      end if;
      exit when v_needed<=0;
    end loop;
    if v_needed>0 then
      raise exception using errcode='22023',message='Insufficient available stock to reserve all tracked order lines';
    end if;
  end loop;
  v_result:=jsonb_build_object('order_id',p_order_id,'reservation_rows',v_count,'reserved_quantity',v_total);
  perform private.finish_idempotent_request(v_order.business_id,'reserve_order_stock',p_request_id,v_result);
  perform private.write_audit(v_order.business_id,v_actor,'stock.order_reserved','order',p_order_id,p_request_id,
    jsonb_build_object('reservation_rows',v_count,'reserved_quantity',v_total));
  return v_result;
end;
$$;

create or replace function private.owner_release_order_reservations(p_order_id uuid,p_reason text,p_request_id uuid)
returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_order public.orders%rowtype; v_actor uuid; v_cached jsonb; v_payload jsonb; v_rows integer; v_result jsonb;
begin
  select * into v_order from public.orders where id=p_order_id;
  if not found then raise exception using errcode='P0002',message='Order not found'; end if;
  v_actor:=private.assert_active_owner(v_order.business_id);
  if length(btrim(coalesce(p_reason,'')))=0 then raise exception using errcode='22023',message='Reservation release reason is required'; end if;
  v_payload:=jsonb_build_object('order_id',p_order_id,'reason',p_reason);
  v_cached:=private.begin_idempotent_request(v_order.business_id,'release_order_reservations',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  perform 1 from public.orders where business_id=v_order.business_id and id=p_order_id for update;
  update public.stock_reservations r set released_quantity=reserved_quantity,status='released',released_at=now()
  where r.business_id=v_order.business_id and r.status='active'
    and r.order_item_id in (select oi.id from public.order_items oi where oi.business_id=v_order.business_id and oi.order_id=p_order_id);
  get diagnostics v_rows=row_count;
  v_result:=jsonb_build_object('order_id',p_order_id,'reservation_rows_released',v_rows);
  perform private.finish_idempotent_request(v_order.business_id,'release_order_reservations',p_request_id,v_result);
  perform private.write_audit(v_order.business_id,v_actor,'stock.reservations_released','order',p_order_id,p_request_id,
    jsonb_build_object('reason',p_reason,'rows',v_rows));
  return v_result;
end;
$$;

create or replace function private.owner_upsert_expense_category(
  p_business_id uuid,p_category_id uuid,p_name text,p_is_active boolean,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_actor uuid; v_cached jsonb; v_payload jsonb; v_id uuid; v_created boolean; v_result jsonb;
begin
  v_actor:=private.assert_active_owner(p_business_id);
  if length(btrim(coalesce(p_name,''))) not between 1 and 100 then raise exception using errcode='22023',message='Expense category name is required'; end if;
  v_payload:=jsonb_build_object('category_id',p_category_id,'name',p_name,'is_active',coalesce(p_is_active,true));
  v_cached:=private.begin_idempotent_request(p_business_id,'upsert_expense_category',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  if p_category_id is null then
    insert into public.expense_categories(business_id,name,is_active) values(p_business_id,btrim(p_name),coalesce(p_is_active,true))
    returning id into v_id; v_created:=true;
  else
    update public.expense_categories set name=btrim(p_name),is_active=coalesce(p_is_active,true)
    where business_id=p_business_id and id=p_category_id returning id into v_id;
    if v_id is null then raise exception using errcode='P0002',message='Expense category not found'; end if;
    v_created:=false;
  end if;
  v_result:=jsonb_build_object('category_id',v_id,'created',v_created);
  perform private.finish_idempotent_request(p_business_id,'upsert_expense_category',p_request_id,v_result);
  perform private.write_audit(p_business_id,v_actor,case when v_created then 'expense_category.created' else 'expense_category.updated' end,
    'expense_category',v_id,p_request_id,'{}'::jsonb);
  return v_result;
end;
$$;

create or replace function private.owner_record_expense(
  p_business_id uuid,p_category_id uuid,p_amount bigint,p_expense_date date,p_payee text,
  p_payment_method text,p_receipt_reference text,p_notes text,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_actor uuid; v_cached jsonb; v_payload jsonb; v_id uuid; v_result jsonb;
begin
  v_actor:=private.assert_active_owner(p_business_id);
  if p_amount is null or p_amount<=0 or p_expense_date is null or p_expense_date>current_date
    or p_payment_method is null or p_payment_method not in ('cash','mpesa','bank','card','other')
    or length(btrim(coalesce(p_payee,''))) not between 1 and 180
    or p_payment_method not in ('cash','mpesa','bank','card','other')
    or length(coalesce(p_receipt_reference,''))>120 or length(coalesce(p_notes,''))>4000 then
    raise exception using errcode='22023',message='Invalid expense details';
  end if;
  if not exists(select 1 from public.expense_categories where business_id=p_business_id and id=p_category_id and is_active) then
    raise exception using errcode='22023',message='Expense category is invalid or inactive';
  end if;
  v_payload:=jsonb_build_object('category_id',p_category_id,'amount',p_amount,'expense_date',p_expense_date,
    'payee',p_payee,'payment_method',p_payment_method,'receipt_reference',p_receipt_reference,'notes',p_notes);
  v_cached:=private.begin_idempotent_request(p_business_id,'record_expense',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  insert into public.expenses(business_id,category_id,amount,expense_date,payee,payment_method,receipt_reference,notes,created_by)
  values(p_business_id,p_category_id,p_amount,p_expense_date,btrim(p_payee),p_payment_method,
    nullif(btrim(p_receipt_reference),''),p_notes,v_actor)
  returning id into v_id;
  v_result:=jsonb_build_object('expense_id',v_id,'amount',p_amount,'currency_code','KES');
  perform private.finish_idempotent_request(p_business_id,'record_expense',p_request_id,v_result);
  perform private.write_audit(p_business_id,v_actor,'expense.recorded','expense',v_id,p_request_id,
    jsonb_build_object('amount',p_amount,'category_id',p_category_id));
  return v_result;
end;
$$;

create or replace function private.owner_record_delivery(
  p_order_id uuid,p_method text,p_carrier text,p_tracking_reference text,
  p_customer_paid_charge bigint,p_recipient_name text,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_order public.orders%rowtype; v_actor uuid; v_cached jsonb; v_payload jsonb; v_id uuid; v_existing public.deliveries%rowtype; v_result jsonb;
begin
  select * into v_order from public.orders where id=p_order_id;
  if not found then raise exception using errcode='P0002',message='Order not found'; end if;
  v_actor:=private.assert_active_owner(v_order.business_id);
  if v_order.status<>'ready' or p_method is null or p_method not in ('collection','courier')
    or p_customer_paid_charge is null or p_customer_paid_charge<0
    or length(btrim(coalesce(p_recipient_name,''))) not between 1 and 180
    or (p_method='courier' and length(btrim(coalesce(p_carrier,'')))=0) then
    raise exception using errcode='22023',message='Order must be ready and delivery details must be valid';
  end if;
  v_payload:=jsonb_build_object('order_id',p_order_id,'method',p_method,'carrier',p_carrier,
    'tracking_reference',p_tracking_reference,'customer_paid_charge',p_customer_paid_charge,'recipient_name',p_recipient_name);
  v_cached:=private.begin_idempotent_request(v_order.business_id,'record_delivery',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  select * into v_existing from public.deliveries
  where business_id=v_order.business_id and order_id=p_order_id and handed_over_at is null
  order by created_at desc,id desc limit 1 for update;
  if found then
    if v_existing.method<>p_method then raise exception using errcode='22023',message='An unhanded delivery already exists with a different method'; end if;
    update public.deliveries set carrier=nullif(btrim(p_carrier),''),tracking_reference=nullif(btrim(p_tracking_reference),''),
      customer_paid_charge=p_customer_paid_charge,recipient_name=btrim(p_recipient_name),
      dispatched_at=case when p_method='courier' then coalesce(dispatched_at,now()) else null end
    where business_id=v_order.business_id and id=v_existing.id returning id into v_id;
  else
    insert into public.deliveries(business_id,order_id,method,carrier,tracking_reference,customer_paid_charge,recipient_name,dispatched_at)
    values(v_order.business_id,p_order_id,p_method,nullif(btrim(p_carrier),''),nullif(btrim(p_tracking_reference),''),
      p_customer_paid_charge,btrim(p_recipient_name),case when p_method='courier' then now() else null end)
    returning id into v_id;
  end if;
  v_result:=jsonb_build_object('delivery_id',v_id,'method',p_method,'customer_paid_charge',p_customer_paid_charge);
  perform private.finish_idempotent_request(v_order.business_id,'record_delivery',p_request_id,v_result);
  perform private.write_audit(v_order.business_id,v_actor,'delivery.recorded','delivery',v_id,p_request_id,
    jsonb_build_object('customer_paid_charge',p_customer_paid_charge,'method',p_method));
  return v_result;
end;
$$;

create or replace function private.owner_update_enquiry_status(
  p_enquiry_id uuid,p_status text,p_notes text,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_enquiry public.enquiries%rowtype; v_actor uuid; v_cached jsonb; v_payload jsonb; v_result jsonb;
begin
  select * into v_enquiry from public.enquiries where id=p_enquiry_id;
  if not found then raise exception using errcode='P0002',message='Enquiry not found'; end if;
  v_actor:=private.assert_active_owner(v_enquiry.business_id);
  if p_status is null or p_status not in ('new','reviewing','quoted','closed','spam') or length(coalesce(p_notes,''))>2000 then
    raise exception using errcode='22023',message='Invalid enquiry status or notes';
  end if;
  if not (
    (v_enquiry.status='new' and p_status in ('reviewing','quoted','closed','spam')) or
    (v_enquiry.status='reviewing' and p_status in ('quoted','closed','spam')) or
    (v_enquiry.status='quoted' and p_status in ('closed')) or
    v_enquiry.status=p_status
  ) then raise exception using errcode='22023',message='Invalid enquiry status transition'; end if;
  v_payload:=jsonb_build_object('enquiry_id',p_enquiry_id,'status',p_status,'notes',p_notes);
  v_cached:=private.begin_idempotent_request(v_enquiry.business_id,'update_enquiry_status',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  update public.enquiries set status=p_status,reviewed_at=case when p_status in ('reviewing','quoted','closed','spam') then now() else reviewed_at end,
    reviewed_by=v_actor
  where business_id=v_enquiry.business_id and id=p_enquiry_id;
  v_result:=jsonb_build_object('enquiry_id',p_enquiry_id,'status',p_status);
  perform private.finish_idempotent_request(v_enquiry.business_id,'update_enquiry_status',p_request_id,v_result);
  perform private.write_audit(v_enquiry.business_id,v_actor,'enquiry.status_changed','enquiry',p_enquiry_id,p_request_id,
    jsonb_build_object('from_status',v_enquiry.status,'to_status',p_status,'notes',p_notes));
  return v_result;
end;
$$;

create or replace function private.owner_create_purchase_order(
  p_business_id uuid,p_supplier_id uuid,p_lines jsonb,p_notes text,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_actor uuid; v_cached jsonb; v_payload jsonb; v_po uuid; v_number text; v_line jsonb;
  v_stock public.stock_items%rowtype; v_qty numeric; v_price bigint; v_count integer:=0; v_result jsonb;
begin
  v_actor:=private.assert_active_owner(p_business_id);
  if not exists(select 1 from public.suppliers where business_id=p_business_id and id=p_supplier_id and archived_at is null)
    or p_lines is null or jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 100 or length(coalesce(p_notes,''))>4000 then
    raise exception using errcode='22023',message='Invalid supplier or purchase order lines';
  end if;
  v_payload:=jsonb_build_object('supplier_id',p_supplier_id,'lines',p_lines,'notes',p_notes);
  v_cached:=private.begin_idempotent_request(p_business_id,'create_purchase_order',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  v_number:=private.next_document_number(p_business_id,'purchase');
  insert into public.purchase_orders(business_id,supplier_id,purchase_number,status,notes,created_by)
  values(p_business_id,p_supplier_id,v_number,'draft',p_notes,v_actor) returning id into v_po;
  for v_line in select value from jsonb_array_elements(p_lines) loop
    if not (v_line ? 'stock_item_id' and v_line ? 'ordered_quantity' and v_line ? 'unit_price') then
      raise exception using errcode='22023',message='Each purchase line requires stock_item_id, ordered_quantity and unit_price';
    end if;
    select * into v_stock from public.stock_items where business_id=p_business_id and id=(v_line->>'stock_item_id')::uuid and is_active for update;
    if not found then raise exception using errcode='22023',message='Purchase line stock item is invalid or inactive'; end if;
    v_qty:=(v_line->>'ordered_quantity')::numeric;
    v_price:=(v_line->>'unit_price')::bigint;
    if v_qty<=0 or v_price<0 then raise exception using errcode='22023',message='Purchase quantity must be positive and price cannot be negative'; end if;
    insert into public.purchase_order_items(business_id,purchase_order_id,stock_item_id,ordered_quantity,purchase_unit,
      purchase_to_base_factor,unit_price,line_total)
    values(p_business_id,v_po,v_stock.id,v_qty,v_stock.purchase_unit,v_stock.purchase_to_base_factor,v_price,round(v_qty*v_price)::bigint);
    v_count:=v_count+1;
  end loop;
  v_result:=jsonb_build_object('purchase_order_id',v_po,'purchase_number',v_number,'status','draft','line_count',v_count);
  perform private.finish_idempotent_request(p_business_id,'create_purchase_order',p_request_id,v_result);
  perform private.write_audit(p_business_id,v_actor,'purchase_order.created','purchase_order',v_po,p_request_id,
    jsonb_build_object('supplier_id',p_supplier_id,'line_count',v_count));
  return v_result;
end;
$$;

create or replace function private.owner_update_purchase_order_status(
  p_purchase_order_id uuid,p_status text,p_reason text,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_po public.purchase_orders%rowtype; v_actor uuid; v_cached jsonb; v_payload jsonb; v_result jsonb;
begin
  select * into v_po from public.purchase_orders where id=p_purchase_order_id;
  if not found then raise exception using errcode='P0002',message='Purchase order not found'; end if;
  v_actor:=private.assert_active_owner(v_po.business_id);
  if p_status not in ('ordered','cancelled') or length(btrim(coalesce(p_reason,'')))=0 then
    raise exception using errcode='22023',message='Invalid purchase order transition or reason';
  end if;
  v_payload:=jsonb_build_object('purchase_order_id',p_purchase_order_id,'status',p_status,'reason',p_reason);
  v_cached:=private.begin_idempotent_request(v_po.business_id,'update_purchase_order_status',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  select * into v_po from public.purchase_orders where business_id=v_po.business_id and id=p_purchase_order_id for update;
  if not ((v_po.status='draft' and p_status in ('ordered','cancelled')) or
    (v_po.status in ('ordered','part_received') and p_status='cancelled')) then
    raise exception using errcode='22023',message='Invalid purchase order status transition';
  end if;
  if p_status='cancelled' and exists(select 1 from public.goods_receipts where business_id=v_po.business_id and purchase_order_id=p_purchase_order_id)
     and v_po.status='ordered' then
    raise exception using errcode='22023',message='Use part_received cancellation for a purchase order with receipt history';
  end if;
  update public.purchase_orders set status=p_status,updated_at=now() where business_id=v_po.business_id and id=p_purchase_order_id;
  v_result:=jsonb_build_object('purchase_order_id',p_purchase_order_id,'status',p_status);
  perform private.finish_idempotent_request(v_po.business_id,'update_purchase_order_status',p_request_id,v_result);
  perform private.write_audit(v_po.business_id,v_actor,'purchase_order.status_changed','purchase_order',p_purchase_order_id,p_request_id,
    jsonb_build_object('from_status',v_po.status,'to_status',p_status,'reason',p_reason));
  return v_result;
end;
$$;

create or replace function private.owner_receive_purchase(
  p_business_id uuid,p_supplier_id uuid,p_purchase_order_id uuid,p_received_at timestamptz,
  p_lines jsonb,p_request_id uuid
) returns jsonb language plpgsql security definer set search_path=''
as $$
declare v_actor uuid; v_cached jsonb; v_payload jsonb; v_po public.purchase_orders%rowtype;
  v_receipt uuid; v_line jsonb; v_po_line public.purchase_order_items%rowtype; v_stock public.stock_items%rowtype;
  v_location uuid; v_accept numeric; v_reject numeric; v_received numeric; v_on_hand numeric;
  v_base_qty numeric; v_base_cost bigint; v_new_avg bigint; v_movement uuid; v_line_id uuid;
  v_count integer:=0; v_result jsonb; v_all_received boolean;
begin
  v_actor:=private.assert_active_owner(p_business_id);
  if p_supplier_id is null or p_received_at is null or p_received_at>now()+interval '5 minutes'
    or p_lines is null or jsonb_typeof(p_lines) is distinct from 'array' or jsonb_array_length(p_lines) not between 1 and 100 then
    raise exception using errcode='22023',message='Invalid goods receipt details';
  end if;
  v_payload:=jsonb_build_object('supplier_id',p_supplier_id,'purchase_order_id',p_purchase_order_id,'received_at',p_received_at,'lines',p_lines);
  v_cached:=private.begin_idempotent_request(p_business_id,'receive_purchase',p_request_id,v_payload);
  if v_cached is not null then return v_cached; end if;
  select * into v_po from public.purchase_orders where business_id=p_business_id and id=p_purchase_order_id for update;
  if not found or v_po.supplier_id<>p_supplier_id or v_po.status not in ('ordered','part_received') then
    raise exception using errcode='22023',message='Purchase order must belong to supplier and be ordered or part received';
  end if;
  insert into public.goods_receipts(business_id,purchase_order_id,received_by,received_at)
  values(p_business_id,p_purchase_order_id,v_actor,p_received_at) returning id into v_receipt;

  for v_line in select value from jsonb_array_elements(p_lines) loop
    if not (v_line ? 'purchase_order_item_id' and v_line ? 'location_id' and v_line ? 'accepted_quantity'
      and v_line ? 'rejected_quantity' and v_line ? 'actual_unit_cost') then
      raise exception using errcode='22023',message='Goods receipt line is missing required fields';
    end if;
    select * into v_po_line from public.purchase_order_items
      where business_id=p_business_id and id=(v_line->>'purchase_order_item_id')::uuid
        and purchase_order_id=p_purchase_order_id for update;
    if not found then raise exception using errcode='22023',message='Purchase order item does not belong to this purchase order'; end if;
    select * into v_stock from public.stock_items where business_id=p_business_id and id=v_po_line.stock_item_id for update;
    v_location:=(v_line->>'location_id')::uuid;
    if not exists(select 1 from public.inventory_locations where business_id=p_business_id and id=v_location and is_active) then
      raise exception using errcode='22023',message='Goods receipt location is invalid';
    end if;
    v_accept:=(v_line->>'accepted_quantity')::numeric;
    v_reject:=(v_line->>'rejected_quantity')::numeric;
    v_base_cost:=(v_line->>'actual_unit_cost')::bigint;
    if v_accept is null or v_reject is null or v_base_cost is null or v_accept<0 or v_reject<0 or v_accept+v_reject<=0 or v_base_cost<0 then
      raise exception using errcode='22023',message='Invalid accepted/rejected quantity or unit cost';
    end if;
    select coalesce(sum(gri.accepted_quantity+gri.rejected_quantity),0) into v_received
    from public.goods_receipt_items gri where gri.business_id=p_business_id and gri.purchase_order_item_id=v_po_line.id;
    if v_received+v_accept+v_reject>v_po_line.ordered_quantity then
      raise exception using errcode='22023',message='Goods received exceed ordered quantity';
    end if;
    v_base_qty:=v_accept*v_po_line.purchase_to_base_factor;
    v_movement:=null;
    if v_accept>0 then
      v_base_cost:=round((v_line->>'actual_unit_cost')::numeric/v_po_line.purchase_to_base_factor)::bigint;
      select coalesce(sum(m.quantity),0) into v_on_hand from public.stock_movements m
      where m.business_id=p_business_id and m.stock_item_id=v_stock.id;
      if v_on_hand<0 then raise exception using errcode='23514',message='Stock on hand cannot be negative during weighted-average receipt'; end if;
      if v_on_hand+v_base_qty>0 then
        v_new_avg:=round((v_on_hand*v_stock.current_average_unit_cost+v_base_qty*v_base_cost)/(v_on_hand+v_base_qty))::bigint;
      else v_new_avg:=v_base_cost; end if;
      update public.stock_items set current_average_unit_cost=v_new_avg,updated_at=now()
      where business_id=p_business_id and id=v_stock.id;
      insert into public.stock_movements(business_id,stock_item_id,location_id,movement_type,quantity,unit_cost_snapshot,
        source_type,source_id,reason,actor_user_id,request_id)
      values(p_business_id,v_stock.id,v_location,'receipt',v_base_qty,v_base_cost,
        'goods_receipt',v_receipt,'Accepted supplier goods received',v_actor,
        private.derived_request_uuid(p_request_id,'receipt-'||v_po_line.id::text))
      returning id into v_movement;
    end if;
    insert into public.goods_receipt_items(business_id,goods_receipt_id,purchase_order_item_id,stock_item_id,location_id,
      accepted_quantity,rejected_quantity,purchase_unit,purchase_to_base_factor,actual_unit_cost,stock_movement_id)
    values(p_business_id,v_receipt,v_po_line.id,v_stock.id,v_location,v_accept,v_reject,
      v_po_line.purchase_unit,v_po_line.purchase_to_base_factor,(v_line->>'actual_unit_cost')::bigint,v_movement)
    returning id into v_line_id;
    v_count:=v_count+1;
  end loop;

  select not exists(
    select 1 from public.purchase_order_items poi
    where poi.business_id=p_business_id and poi.purchase_order_id=p_purchase_order_id
      and coalesce((select sum(gri.accepted_quantity) from public.goods_receipt_items gri
        where gri.business_id=poi.business_id and gri.purchase_order_item_id=poi.id),0)<poi.ordered_quantity
  ) into v_all_received;
  update public.purchase_orders set status=case when v_all_received then 'received' else 'part_received' end,updated_at=now()
  where business_id=p_business_id and id=p_purchase_order_id;
  v_result:=jsonb_build_object('goods_receipt_id',v_receipt,'purchase_order_id',p_purchase_order_id,
    'status',case when v_all_received then 'received' else 'part_received' end,'line_count',v_count);
  perform private.finish_idempotent_request(p_business_id,'receive_purchase',p_request_id,v_result);
  perform private.write_audit(p_business_id,v_actor,'purchase.received','goods_receipt',v_receipt,p_request_id,
    jsonb_build_object('purchase_order_id',p_purchase_order_id,'line_count',v_count));
  return v_result;
end;
$$;

-- Blank stock is physically issued exactly once when an order is handed over.
create or replace function private.consume_blank_stock_on_handover()
returns trigger language plpgsql security definer set search_path=''
as $$
declare v_line record; v_reservation record; v_actor uuid; v_qty numeric; v_cost bigint;
begin
  if old.status='ready' and new.status='completed' then
    v_actor:=auth.uid();
    if v_actor is null then raise exception using errcode='42501',message='Authenticated owner required for stock handover'; end if;
    for v_line in
      select oi.id,oi.stock_item_id from public.order_items oi
      where oi.business_id=new.business_id and oi.order_id=new.id
         and oi.stock_item_id is not null and oi.customer_supplies_item=false
    loop
      if coalesce((select sum(r.reserved_quantity-r.released_quantity) from public.stock_reservations r
        where r.business_id=new.business_id and r.order_item_id=v_line.id and r.status='active'),0)
        < (select oi.quantity from public.order_items oi where oi.business_id=new.business_id and oi.id=v_line.id) then
        raise exception using errcode='23514',message='Blank product stock must be reserved before handover';
      end if;
      for v_reservation in
        select r.* from public.stock_reservations r
        where r.business_id=new.business_id and r.order_item_id=v_line.id and r.status='active'
        order by r.created_at,r.id for update
      loop
        v_qty:=v_reservation.reserved_quantity-v_reservation.released_quantity;
        if v_qty>0 then
          select current_average_unit_cost into v_cost from public.stock_items
          where business_id=new.business_id and id=v_reservation.stock_item_id for update;
          insert into public.stock_movements(business_id,stock_item_id,location_id,movement_type,quantity,unit_cost_snapshot,
            source_type,source_id,reason,actor_user_id,request_id)
          values(new.business_id,v_reservation.stock_item_id,v_reservation.location_id,'issue',-v_qty,v_cost,
            'order_handover',new.id,'Tracked blank item sold and handed over',v_actor,gen_random_uuid());
          update public.stock_reservations set released_quantity=reserved_quantity,status='consumed',released_at=now()
          where business_id=new.business_id and id=v_reservation.id;
        end if;
      end loop;
    end loop;
  end if;
  return new;
end;
$$;
create trigger orders_consume_blank_stock
before update of status on public.orders
for each row execute function private.consume_blank_stock_on_handover();

