 p_base_unit text,p_purchase_unit text,p_purchase_to_base_factor numeric,p_roll_width_mm numeric,p_usable_width_mm numeric,
 p_variant_attributes jsonb,p_reorder_level numeric,p_default_supplier_id uuid,p_request_id uuid
